import fs from 'node:fs';
const dir = new URL('../public/logos/', import.meta.url);
const out = {};
for (const f of fs.readdirSync(dir)) {
  if (!f.endsWith('.svg')) continue;
  const s = fs.readFileSync(new URL(f, dir), 'utf8');
  const vb = s.match(/viewBox="([^"]+)"/)[1];
  let inner = s.replace(/^[\s\S]*?<svg[^>]*>/, '').replace(/<\/svg>\s*$/, '').replace(/<title>[\s\S]*?<\/title>/, '').trim();
  out[f.replace('.svg', '')] = { viewBox: vb, inner };
}
fs.writeFileSync(new URL('../src/logos-data.ts', import.meta.url),
  '// Generated by scripts/gen-logos.mjs from public/logos/*.svg\nexport const LOGOS = ' + JSON.stringify(out, null, 1) + ' as const;\nexport type LogoName = keyof typeof LOGOS;\n');
console.log(Object.keys(out));
